    let caller: Caller;
    try {
      caller = await deps.verify(token ? `Bearer ${token}` : undefined);
    } catch {
      return { statusCode: 401, body: "sign in first" };
    }
    await deps.live.connect(connectionId, caller.sub, now());
    return { statusCode: 200 };
