      from: m["from"],
      run: m["run"],
      seq: m["seq"],
      ref: m["ref"],
      press: m["press"],
      ...(typeof m["move"] === "string" ? { move: m["move"] } : {}),
      ...(m["answer"] && typeof m["answer"] === "object" ? { answer: m["answer"] as Record<string, unknown> } : {}),
    };
  } catch {
    return null;
  }
}
