import { bearer, credentials } from "./packages/cli/src/account.ts";
const t = await bearer(credentials());
const ws = new WebSocket(`wss://runlog.dev.scrthq.com/ws?token=${encodeURIComponent(t)}&as=deck`);
let run = null, seq = null, pressed = false;
const log = (...a) => console.log(new Date().toISOString().slice(11, 23), ...a);
ws.addEventListener("open", () => { log("open → hello"); ws.send(JSON.stringify({ t: "hello" })); });
ws.addEventListener("message", (e) => {
  const m = JSON.parse(String(e.data));
  if (m.t === "runs") { log("runs:", JSON.stringify(m.runs)); if (!run && m.runs[0]) { run = m.runs[0].id; ws.send(JSON.stringify({ t: "watch", id: run })); log("watching", run); } }
  else if (m.t === "changed" && m.id === run) { seq = m.seq; log("changed seq", seq); }
  else if (m.t === "gesture") log("gesture", m.kind, JSON.stringify(m.data).slice(0, 120));
  else if (m.t === "drove") { log("drove:", JSON.stringify(m)); }
  else log("msg", String(e.data).slice(0, 160));
});
ws.addEventListener("close", (e) => log("close", e.code));
ws.addEventListener("error", (e) => log("error", e.message));
// After 5 s, press the primary once with the seq we hold (0 if none arrived yet — the page will say so).
setTimeout(() => { if (run && !pressed) { pressed = true; const s = seq ?? 0; log("press primary with seq", s); ws.send(JSON.stringify({ t: "drive", run, seq: s, ref: "probe-" + Date.now().toString(36), press: "primary" })); } else log("nothing to press (run=" + run + ")"); }, 5000);
setTimeout(() => { ws.close(); setTimeout(() => process.exit(0), 300); }, 11000);
' 2>&1 | head -30

