# The heaviest thing in the game, and the weight to carry it.
#
# Bull-Goat is the fattest armor there is and the reason the equip load
# talisman is here: without it this is a loadout that rolls like a barrel.
# Strength is set rather than hoped for, because Giant-Crusher asks for a
# great deal of it and a colossal hammer nobody can lift is a joke, not a
# gift.

# yaml-language-server: $schema=../../packages/rules-schema/schema/setup-1.schema.json

kind: setup
schemaVersion: 1
id: com.scrthq.runlog.setups.brute
version: "1.0.0"
title: Brute
author: Runlog
description: >-
  A colossal hammer, the heaviest armor in the game, and the strength and
  endurance to move in it. Nothing here is subtle and none of it needs to be.

tool: TarnishedTool

ops:
  - { op: value.set, args: { name: player.strength, value: 70 } }
  - { op: value.set, args: { name: player.endurance, value: 50 } }
---
}

export function nextFace(state: DeckState): Face {
  const c = common(state) ?? flashed(state);
  if (c) return c;
  const offer = state.snapshot?.offer;
  if (!offer) return { title: "Loading…", tone: "dim" };
  if (offer.primary) return { title: offer.primary.label, tone: "live" };
  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
}

export function pressFace(state: DeckState, target: PressTarget): Face {
  const c = common(state) ?? flashed(state);
  if (c) return c;
  const offer = state.snapshot?.offer;
  if (!offer) return { title: "Loading…", tone: "dim" };
  if (target.kind === "roll")
    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
  if (target.kind === "move") {
    const m = offer.moves.find((x) => x.id === target.id);
    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
  }
  const p = offer.presets.find((x) => x.kind === target.preset);
  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
}

export function undoFace(state: DeckState): Face {
  const c = common(state) ?? flashed(state);
  if (c) return c;
  const undo = state.snapshot?.offer?.undo;
  return undo ? { title: "Undo", tone: "live", when: undo.what } : { title: "Nothing to undo", tone: "dim" };
}

export function runFace(state: DeckState): Face {
  return common(state) ?? attachedName(state) ?? { title: "Pick a run", tone: "dim" };
}

