    url: async () => socketUrl(base, await account.getAccessToken()),
    onChanged: (changed) => {
      if (changed.id === lastActive()?.runId) void run();
    },
    onGesture: (g) =>
      syncBus.emit({ t: "gesture", id: g.id, kind: g.kind, data: g.data, ...(g.from ? { from: g.from } : {}), at: g.at }),
