        ...(d.answer !== undefined ? { answer: d.answer } : {}),
      }),
    onState: (open) => {
      socketOpen = open;
    },
  });
  socketRef.current = socket;
  watchCurrent();
};
const closeSocket = () => {
  socket?.close();
