git diff --stat 3b5e06d 2a5a126 && git log -1 --format=%B 2a5a126 | grep -ci "co-authored\|claude-session" ; sed -n 56,66p streamdeck/src/face.ts; cat > streamdeck/src/_r.mts <<'EOF'
import { faceImage } from "./face.ts";
import { writeFileSync } from "node:fs";
import { Resvg } from "@resvg/resvg-js";
const faces = [
  { title: "Blessing", tone: "live" }, { title: "Tick everything and Next", tone: "live" },
  { title: "Exalted Flesh", tone: "live", when: "Name what you are going for" }, { title: "Draw what is wrong with the world", tone: "live" },
  { title: "Not connected", tone: "dim", when: "press Connect" }, { title: "Offline", tone: "dim" },
  { title: "4/10", tone: "live", when: "Scenes before a warp" }, { title: "Connecting", tone: "dim" },
];
const w = 144, gap = 8, cols = 4;
const canvas = new Resvg(`<svg xmlns="http://www.w3.org/2000/svg" width="${cols*(w+gap)}" height="${2*(w+gap)}"><rect width="100%" height="100%" fill="#000"/></svg>`).render();
const { createCanvasLike } = {} as never; void createCanvasLike;
// Compose by rendering each face at 144px and pasting pixels.
const out = Buffer.alloc(cols*(w+gap) * 2*(w+gap) * 4);
faces.forEach((f, i) => {
  const svg = Buffer.from(faceImage(f as never).split(",")[1]!, "base64").toString("utf8");
  const px = new Resvg(svg, { fitTo: { mode: "width", value: w }, font: { loadSystemFonts: true } }).render().pixels;
  const ox = (i % cols) * (w + gap), oy = Math.floor(i / cols) * (w + gap), W = cols*(w+gap);
  for (let y = 0; y < w; y++) px.copy(out, ((oy + y) * W + ox) * 4, y * w * 4, (y + 1) * w * 4);
});
const png = new Resvg(`<svg xmlns="http://www.w3.org/2000/svg" width="1" height="1"/>`).render();
void png; void canvas;
// Write raw RGBA as PNG via resvg's helper is not exposed; emit a PPM the Read tool cannot show, so wrap into a BMP-less PNG using zlib.
import { deflateSync } from "node:zlib";
const W = cols*(w+gap), H = 2*(w+gap);
const crc = (buf: Buffer) => { let c = ~0; for (const b of buf) { c ^= b; for (let k = 0; k < 8; k++) c = (c >>> 1) ^ (0xedb88320 & -(c & 1)); } return ~c >>> 0; };
const chunk = (type: string, data: Buffer) => { const len = Buffer.alloc(4); len.writeUInt32BE(data.length); const td = Buffer.concat([Buffer.from(type), data]); const c = Buffer.alloc(4); c.writeUInt32BE(crc(td)); return Buffer.concat([len, td, c]); };
const raw = Buffer.alloc((W * 4 + 1) * H);
for (let y = 0; y < H; y++) { raw[y * (W * 4 + 1)] = 0; out.copy(raw, y * (W * 4 + 1) + 1, y * W * 4, (y + 1) * W * 4); }
const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(W, 0); ihdr.writeUInt32BE(H, 4); ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
writeFileSync(process.argv[2]!, Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]), chunk("IHDR", ihdr), chunk("IDAT", deflateSync(raw)), chunk("IEND", Buffer.alloc(0))]));
console.log("ok");
EOF
