cat > "$TEMP/patch-export2.cjs" <<'EOF'
const fs = require("fs");
const p = "streamdeck/design/export.mjs";
const raw = fs.readFileSync(p, "utf8");
const nl = raw.includes("\r\n") ? "\r\n" : "\n";
const lines = raw.split(/\r?\n/);
const start = lines.findIndex((l) => l === "function body(svg) {");
if (start < 0) throw new Error("no function");
let end = start;
while (lines[end] !== "}") end++;
const repl = [
  "function body(svg) {",
  '  let inner = svg.replace(/^[\\s\\S]*?<svg[^>]*>/, "").replace(/<\\/svg>\\s*$/, "");',
  "  // To a fixed point, so a comment left behind by removing another (one",
  "  // that had `<!--` inside it) goes too. These are our own drawings, but",
  "  // the markup ends up inside every key face, and a scanner is right to",
  "  // want the pass to finish what it starts.",
  '  for (let before = ""; before !== inner; ) {',
  "    before = inner;",
  '    inner = inner.replace(/<!--[\\s\\S]*?-->/g, "");',
  "  }",
  '  return inner.replace(/\\s+/g, " ").trim();',
  "}",
];
lines.splice(start, end - start + 1, ...repl);
fs.writeFileSync(p, lines.join(nl));
console.log("patched", start, end);
EOF
